-- Migration 005: audit_runs table
-- Stores every AuditReport v2 generated by the AuditOrchestrator,
-- regardless of entry point (escrow_task, x402_service, analyze_page).

CREATE TABLE IF NOT EXISTS audit_runs (
  id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  task_id               UUID REFERENCES tasks(id) ON DELETE SET NULL,
  entry_point           TEXT NOT NULL CHECK (entry_point IN ('escrow_task','x402_service','analyze_page')),
  source_hash           TEXT NOT NULL,
  score                 INTEGER NOT NULL CHECK (score >= 0 AND score <= 100),
  verdict               TEXT NOT NULL CHECK (verdict IN ('PASS','REVIEW_REQUIRED','FAIL')),
  report_json           JSONB NOT NULL,
  blockrun_receipt      JSONB,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS audit_runs_task_id_idx     ON audit_runs(task_id);
CREATE INDEX IF NOT EXISTS audit_runs_source_hash_idx ON audit_runs(source_hash);
CREATE INDEX IF NOT EXISTS audit_runs_verdict_idx      ON audit_runs(verdict);
CREATE INDEX IF NOT EXISTS audit_runs_created_at_idx   ON audit_runs(created_at DESC);
